"""Grader: behaviour must match the original module; the repeated block must be gone."""
import importlib
import re
import sys
import unittest
from pathlib import Path

import pricing
import pricing_original as orig

# Statements of the block that was copied three times; each may now appear once.
KEY = [
    'name=str(item.get("name","")).strip()',
    'qty=int(item.get("qty",1))',
    'price=round(float(item["price"]),2)',
    'amount=round(qty*price,2)',
]


def squash(line):
    return re.sub(r"\s+", "", line).replace("'", '"')


def repeated_windows(text):
    lines = [squash(ln) for ln in text.splitlines()]
    return [k for k in KEY if lines.count(k) > 1]


ITEMS = [
    [{"name": "pen", "qty": 3, "price": 2.5}],
    [{"name": " ink ", "qty": 1, "price": "4.499"}, {"name": "pad", "qty": 12, "price": 0.35}],
    [{"name": "a", "price": 10}, {"name": "b", "qty": 100, "price": 1.1}],
    [],
    [{"name": "x", "qty": 2, "price": 0}],
]
BAD = [
    [{"name": "", "qty": 1, "price": 1}],
    [{"price": 1}],
    [{"name": "n", "qty": 0, "price": 1}],
    [{"name": "n", "qty": -2, "price": 1}],
    [{"name": "n", "qty": 1, "price": -0.01}],
    [{"name": "n", "qty": "two", "price": 1}],
    [{"name": "n"}],
]


def outcome(fn, *a, **k):
    try:
        return ("ok", fn(*a, **k))
    except Exception as e:  # compare the type and message too
        return (type(e).__name__, str(e))


class Behaviour(unittest.TestCase):
    def same(self, name, *a, **k):
        self.assertEqual(outcome(getattr(pricing, name), *a, **k), outcome(getattr(orig, name), *a, **k), (name, a, k))

    def test_retail(self):
        for items in ITEMS + BAD:
            for coupon in (None, "save5", " ten ", "TEN", "nope"):
                self.same("quote_retail", items, coupon=coupon)

    def test_wholesale(self):
        for items in ITEMS + BAD:
            for tier in ("bronze", "silver", "gold", "platinum"):
                for min_lines in (1, 2):
                    self.same("quote_wholesale", items, tier=tier, min_lines=min_lines)

    def test_staff(self):
        for items in ITEMS + BAD:
            for used in (0.0, 150.0, 199.99, 250.0):
                self.same("quote_staff", items, used_this_year=used)

    def test_describe_and_defaults(self):
        q = pricing.quote_staff(ITEMS[1])
        self.assertEqual(pricing.describe(q), orig.describe(orig.quote_staff(ITEMS[1])))
        self.same("quote_retail", ITEMS[0])
        self.same("quote_wholesale", ITEMS[0])
        self.same("quote_staff", ITEMS[0])
        self.assertEqual((pricing.TAX_RATE, pricing.STAFF_LIMIT), (orig.TAX_RATE, orig.STAFF_LIMIT))

    def test_no_repeated_block(self):
        dup = repeated_windows(Path("pricing.py").read_text())
        self.assertEqual(dup, [], "the copied block still appears more than once: %r" % dup)


if __name__ == "__main__":
    unittest.main()

